import{_ as d,C as o,o as r,c as n,E as a,a4 as i}from"./chunks/framework.BMj-uaUw.js";const f=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[{"level":2,"title":"从一个真实的抱怨说起","slug":"从一个真实的抱怨说起","link":"#从一个真实的抱怨说起","children":[]},{"level":2,"title":"本单元的知识地图","slug":"本单元的知识地图","link":"#本单元的知识地图","children":[]},{"level":2,"title":"这次课的 4 学时怎么用","slug":"这次课的-4-学时怎么用","link":"#这次课的-4-学时怎么用","children":[]},{"level":2,"title":"开始之前","slug":"开始之前","link":"#开始之前","children":[]},{"level":2,"title":"这个单元的产出","slug":"这个单元的产出","link":"#这个单元的产出","children":[]},{"level":2,"title":"术语约定","slug":"术语约定","link":"#术语约定","children":[]},{"level":2,"title":"读完之后","slug":"读完之后","link":"#读完之后","children":[]}],"relativePath":"unit08/index.md","filePath":"unit08/index.md","lastUpdated":1789356894000}'),l={name:"unit08/index.md"};function c(s,t,h,u,p,g){const e=o("UnitMeta");return r(),n("div",null,[a(e,{unit:"单元 8",title:"组件进阶与逻辑复用",module:"模块三 · 组件化开发",hours:"4 学时",week:"第 8 周",goals:["能用插槽实现内容分发","能把重复逻辑抽成组合式函数","能按需使用内置组件提升交互体验","能编写解决 DOM 层通用问题的自定义指令"],outcomes:["可复用弹窗与全局通知","自研组合式函数集"]}),t[0]||(t[0]=i('<h2 id="从一个真实的抱怨说起" tabindex="-1">从一个真实的抱怨说起 <a class="header-anchor" href="#从一个真实的抱怨说起" aria-label="Permalink to &quot;从一个真实的抱怨说起&quot;">​</a></h2><p>第七周你写完了活动列表和活动详情，组件拆得很干净。但到了这周，问题冒出来了。</p><p>第一件：你想做一个弹窗组件，发现它只能显示固定的文字和按钮 —— 活动详情页要显示“确认通过这条报名吗”， 审核页要显示“确认驳回并填写理由？”，弹窗里的内容完全不一样，可你在组件里写死了。 要想复用，要么把内容做成一大串 props（<code>title</code>、<code>content</code>、<code>confirmText</code>、<code>cancelText</code>……）， 要么复制好几份。</p><p>第二件：活动详情页里有三层嵌套：页面 → 活动卡片 → 报名按钮。报名按钮要拿到“当前登录用户的角色” 才能决定自己显不显示。你不想从页面一路传 props 传到第三层，中间那层根本不关心这个数据。</p><p>第三件：好几个页面都要“把数据存到 localStorage 里并且保持响应”，你发现自己复制了三遍同样的代码， 改的时候还要一个个改。</p><p>这三件麻烦事，分别对应这个单元的四个知识点：<strong>插槽、依赖注入、组合式函数、自定义指令</strong>。 它们解决的是同一个大问题：<strong>组件写好之后，怎么让它更通用、让逻辑更值钱。</strong></p><div class="tip custom-block"><p class="custom-block-title">这个单元的位置</p><p>第七周解决的是“组件之间怎么通信”—— props 往下传、emits 往上报，也就是父子通信。 这个单元解决的是“组件怎么变得更通用”—— 内容能不能由使用者决定？深层组件怎么拿数据？ 重复的逻辑能不能抽出来复用？</p><p><strong>如果说第七周让你会拆组件，这一周让你会做“能被别人用”的组件。</strong></p></div><h2 id="本单元的知识地图" tabindex="-1">本单元的知识地图 <a class="header-anchor" href="#本单元的知识地图" aria-label="Permalink to &quot;本单元的知识地图&quot;">​</a></h2><table tabindex="0"><thead><tr><th>小节</th><th>讲什么</th><th>解决什么问题</th></tr></thead><tbody><tr><td><a href="/frontend-engineering-course/unit08/01-slots.html">8.1 插槽</a></td><td>默认插槽、具名插槽、作用域插槽、后备内容</td><td>组件要显示的内容由使用者决定</td></tr><tr><td><a href="/frontend-engineering-course/unit08/02-provide-inject.html">8.2 依赖注入</a></td><td><code>provide</code> / <code>inject</code>、响应性、只读封装、Symbol 键</td><td>越过中间层，给深层组件传数据</td></tr><tr><td><a href="/frontend-engineering-course/unit08/03-builtin.html">8.3 内置组件</a></td><td><code>Transition</code>、<code>TransitionGroup</code>、<code>KeepAlive</code>、<code>Teleport</code>、<code>Suspense</code></td><td>动画、缓存、传送、异步加载开箱可用</td></tr><tr><td><a href="/frontend-engineering-course/unit08/04-composables.html">8.4 组合式函数</a></td><td><code>use</code> 前缀、参数与返回值、三个实战</td><td>把“状态 + 逻辑”打包成可复用函数</td></tr><tr><td><a href="/frontend-engineering-course/unit08/05-directives.html">8.5 自定义指令</a></td><td>钩子函数、<code>binding</code> 参数、三个实战指令</td><td>解决需要直接操作 DOM 的通用问题</td></tr><tr><td><a href="/frontend-engineering-course/unit08/06-case-modal.html">案例 06 · 模态框与全局通知</a></td><td>Teleport 模态框、模块级 ref、<code>useToast</code></td><td>做一个能全站用的弹窗与通知系统</td></tr><tr><td><a href="/frontend-engineering-course/unit08/07-case-canvas.html">案例 08 · 画板与撤销重做</a></td><td>指针事件、双栈撤销重做、导出图片</td><td>挑战档加分任务</td></tr><tr><td><a href="/frontend-engineering-course/unit08/ai-collaboration.html">AI 协作 · 状态放错位置的坑</a></td><td>模块作用域导致多实例共享、组合式函数不清副作用、指令生命周期</td><td>复用组件时状态互相污染</td></tr></tbody></table><p>这几节里，8.1 到 8.3 是“用 Vue 提供的工具”，8.4 和 8.5 是“自己造工具”。 两个案例是把它们串起来用。</p><h2 id="这次课的-4-学时怎么用" tabindex="-1">这次课的 4 学时怎么用 <a class="header-anchor" href="#这次课的-4-学时怎么用" aria-label="Permalink to &quot;这次课的 4 学时怎么用&quot;">​</a></h2><table tabindex="0"><thead><tr><th>环节</th><th>时长</th><th>做什么</th></tr></thead><tbody><tr><td>检查预习</td><td>0.3 学时</td><td>抽问：第七周的 props 与 emits 分别解决什么方向的数据流动？</td></tr><tr><td>讲解</td><td>1.5 学时</td><td>重点讲 8.1 三种插槽与 8.4 组合式函数；8.3 以现场演示为主</td></tr><tr><td>现场任务</td><td>1.7 学时</td><td>分两组：一组做案例 06 的弹窗与通知，一组做 8.5 的三个指令；完成后交换讲评</td></tr><tr><td>复盘</td><td>0.5 学时</td><td>展示一份组合式函数，讨论“哪些逻辑值得抽”的判断标准</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">最容易混的一个概念</p><p>插槽和 props 都能“给组件传东西”，新手最容易混。记住两句话：</p><ul><li><strong>传数据用 props</strong> —— 组件需要的是“一个值”，比如 <code>title=&quot;活动列表&quot;</code>。</li><li><strong>传结构用插槽</strong> —— 组件需要的是“一段界面”，比如“按钮长什么样由你来定”。</li></ul><p>判断方法：如果这个内容里含有 HTML 标签或者另一个组件，那就是结构，用插槽。</p></div><h2 id="开始之前" tabindex="-1">开始之前 <a class="header-anchor" href="#开始之前" aria-label="Permalink to &quot;开始之前&quot;">​</a></h2><p>这个单元假设你已经会：</p><ul><li>用 <code>defineProps</code> 声明属性、用 <code>defineEmits</code> 声明事件（<a href="/frontend-engineering-course/unit07/02-props.html">单元 7</a>）。</li><li>用 <code>ref</code> / <code>computed</code> / <code>watch</code> 写响应式逻辑（<a href="/frontend-engineering-course/unit04/04-reactivity.html">单元 4</a>、<a href="/frontend-engineering-course/unit05/01-computed.html">单元 5</a>）。</li><li>组件挂载与卸载的时机、在 <code>onUnmounted</code> 里清理副作用（<a href="/frontend-engineering-course/unit06/05-lifecycle.html">单元 6</a>）。</li></ul><p>如果这三项里有一项不熟，先回去补。这个单元不会重复讲它们，而是直接拿它们当基础往上搭。</p><h2 id="这个单元的产出" tabindex="-1">这个单元的产出 <a class="header-anchor" href="#这个单元的产出" aria-label="Permalink to &quot;这个单元的产出&quot;">​</a></h2><p><strong>一、可复用弹窗与全局通知</strong></p><p>做成一个能放进任何一个页面的能力：</p><ul><li>一个用 <code>Teleport</code> 送到 <code>body</code> 下的模态框，能锁背景滚动、能按 Esc 关闭、关闭后焦点回到原处。</li><li>一个 <code>useToast</code> 组合式函数，任何地方调用 <code>push(&#39;报名审核通过&#39;)</code> 就能弹出一条自动消失的提示。</li><li>多条通知能堆叠、能手动关闭、进出有动画。</li></ul><p><strong>二、自研组合式函数集</strong></p><p>放在 <code>src/composables/</code> 目录下，至少包含：</p><table tabindex="0"><thead><tr><th>函数</th><th>作用</th></tr></thead><tbody><tr><td><code>useLocalStorage</code></td><td>读写本地存储并保持响应，处理序列化与解析失败</td></tr><tr><td><code>useMouse</code></td><td>跟踪鼠标位置，挂载时监听、卸载时清理</td></tr><tr><td><code>useRequest</code></td><td>封装异步请求的加载态、错误态、数据、重试与取消</td></tr></tbody></table><details class="details custom-block"><summary>合格与不合格的差别</summary><p><strong>不合格</strong>：三个函数写在同一个文件里，互相调用，每个都依赖组件里的具体业务（比如直接写了 “活动列表接口地址”）。换一个页面就用不了。</p><p><strong>合格</strong>：每个函数一个文件，只依赖传入的参数，不依赖任何业务概念。<code>useLocalStorage(&#39;draft&#39;, &#39;&#39;)</code> 在活动编辑页能用，在报名表单页也能用。<strong>判断标准是“能不能原样搬到另一个项目里”。</strong></p></details><h2 id="术语约定" tabindex="-1">术语约定 <a class="header-anchor" href="#术语约定" aria-label="Permalink to &quot;术语约定&quot;">​</a></h2><table tabindex="0"><thead><tr><th>术语</th><th>在这里指什么</th></tr></thead><tbody><tr><td>插槽</td><td>组件模板里用 <code>&lt;slot&gt;</code> 留出的位置，用组件的人往里填内容</td></tr><tr><td>依赖注入</td><td><code>provide</code> 往下提供值、<code>inject</code> 往上取值的机制</td></tr><tr><td>组合式函数</td><td>以 <code>use</code> 开头的函数，内部封装状态与逻辑，返回可用的值</td></tr><tr><td>自定义指令</td><td>以 <code>v-</code> 开头、注册后能写在标签上的能力，用来直接操作 DOM</td></tr></tbody></table><h2 id="读完之后" tabindex="-1">读完之后 <a class="header-anchor" href="#读完之后" aria-label="Permalink to &quot;读完之后&quot;">​</a></h2><p>先读 <a href="/frontend-engineering-course/unit08/01-slots.html">8.1 插槽</a>。插槽是这一周最常用的能力，几乎每个通用组件都会用到。 其余几节按顺序读即可，8.4 和 8.5 是这周的重头戏，需要动手写代码。</p>',29))])}const b=d(l,[["render",c]]);export{f as __pageData,b as default};
